// Plantilla de precios por defecto por rubro. "vehicle_type" para salon
// guarda la categoria de estilista (junior/senior), en minuscula -- la
// consulta de precios ya normaliza a minuscula y sin espacios de los dos
// lados, asi que el valor exacto que guarda lead_state ("Junior"/"Senior")
// matchea igual.
const PRICING_TEMPLATES = {
  detailing: [
    ["lavado_basico", "sedan", 25000],
    ["lavado_basico", "suv", 30000],
    ["lavado_basico", "camioneta", 32000],
    ["lavado_premium", "sedan", 35000],
