    ["lavado_premium", "camioneta", 45000],
    ["encerado_full", "sedan", 60000],
    ["encerado_full", "suv", 70000],
    ["encerado_full", "camioneta", 80000]
  ],
  salon: [
    ["corte", "junior", 8000],
    ["corte", "senior", 15000],
    ["color", "junior", 20000],
    ["color", "senior", 35000],
    ["manicure", "junior", 8000],
    ["manicure", "senior", 12000],
    ["tratamiento_facial", "junior", 15000],
    ["tratamiento_facial", "senior", 25000],
    ["peinado", "junior", 10000],
    ["peinado", "senior", 18000]
  ]
};

const businessConfig = error ? null : BUSINESS_CONFIG_TEMPLATES[vertical]();
const pricingRows = error ? [] : PRICING_TEMPLATES[vertical];

return [{
  json: {
    valid: !error,
    error,
    vertical,
    user_id: userId || null,
    organization_id: organizationId || null,
    agent_name: agentName || null,
    description: `Agente de ${vertical} creado por onboarding`,
    slug,
    business_config: businessConfig,
    pricing_rows: pricingRows,
    channel: channelInput
  }
}];

const input = $json || {};

function sqlText(value) {
  if (value === undefined || value === null || value === "") return "NULL";
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function sqlUuidOrNull(value) {
  const text = String(value || "").trim();
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
  return isUuid ? "'" + text + "'" : "NULL";
}

function sqlJsonb(value) {
  const json = JSON.stringify(value === undefined ? null : value);
  return "'" + json.replace(/'/g, "''") + "'::jsonb";
}

function sqlNumber(value) {
  const num = Number(value);
  return Number.isFinite(num) ? String(num) : "NULL";
}

if (!input.valid) {
  return [{ json: { ...input, create_agent_query: null } }];
}

const pricingRows = Array.isArray(input.pricing_rows) ? input.pricing_rows : [];
const pricingValues = pricingRows
  .map((row) => `(${sqlText(row[0])}, ${sqlText(row[1])}, ${sqlNumber(row[2])})`)
  .join(",\n      ");

const query = `
WITH membership AS (
  SELECT EXISTS (
    SELECT 1 FROM organization_members
    WHERE user_id = ${sqlUuidOrNull(input.user_id)}
      AND organization_id = ${sqlUuidOrNull(input.organization_id)}
  ) AS is_member
),
new_agent AS (
  INSERT INTO agents (organization_id, slug, name, role, is_active)
  SELECT ${sqlUuidOrNull(input.organization_id)}, ${sqlText(input.slug)}, ${sqlText(input.agent_name)}, 'closer', true
  FROM membership WHERE membership.is_member
  RETURNING id, organization_id
),
new_business_config AS (
  INSERT INTO agent_business_config (organization_id, agent_id, version, is_active, config)
  SELECT organization_id, id, 1, true, ${sqlJsonb(input.business_config)}
  FROM new_agent
  RETURNING id, agent_id
),
new_pricing_version AS (
  INSERT INTO pricing_versions (agent_id, name, is_active, valid_from)
  SELECT id, 'onboarding_v1', true, now()
  FROM new_agent
  RETURNING id, agent_id
),
new_prices AS (
  INSERT INTO service_vehicle_prices (pricing_version_id, service_code, vehicle_type, base_price, is_active)
  SELECT npv.id, v.service_code, v.vehicle_type, v.base_price, true
  FROM new_pricing_version npv
  CROSS JOIN (
    VALUES
      ${pricingValues}
  ) AS v(service_code, vehicle_type, base_price)
  RETURNING id
)
SELECT
  (SELECT is_member FROM membership) AS is_member,
  (SELECT id FROM new_agent) AS agent_id,
  (SELECT organization_id FROM new_agent) AS organization_id,
  (SELECT id FROM new_business_config) AS business_config_id,
  (SELECT id FROM new_pricing_version) AS pricing_version_id,
  (SELECT count(*) FROM new_prices) AS prices_created;
`;

return [{
  json: {
    ...input,
    create_agent_query: query
  }
}];

const upstream = $("build_create_agent_query").first().json;
const dbResult = $json || {};

function sqlText(value) {
  if (value === undefined || value === null || value === "") return "NULL";
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function sqlUuidOrNull(value) {
  const text = String(value || "").trim();
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text);
  return isUuid ? "'" + text + "'" : "NULL";
}

const isMember = dbResult.is_member === true || dbResult.is_member === "t" || dbResult.is_member === "true";
const agentId = dbResult.agent_id || null;

let status = "ok";
if (!isMember) status = "forbidden";
else if (!agentId) status = "creation_failed";

const channel = upstream.channel && typeof upstream.channel === "object" ? upstream.channel : null;
let channelInsertQuery = null;

if (status === "ok" && channel && channel.channel && channel.provider && channel.external_channel_id) {
  channelInsertQuery = `
INSERT INTO agent_channels (organization_id, agent_id, channel, provider, external_channel_id, display_name, is_active)
VALUES (
  ${sqlUuidOrNull(dbResult.organization_id)},
  ${sqlUuidOrNull(agentId)},
  ${sqlText(channel.channel)},
  ${sqlText(channel.provider)},
  ${sqlText(channel.external_channel_id)},
  ${sqlText(channel.display_name || upstream.agent_name)},
  true
)
RETURNING id;
`;
}

return [{
  json: {
    status,
    agent_id: agentId,
    organization_id: dbResult.organization_id || upstream.organization_id || null,
    slug: upstream.slug || null,
    agent_name: upstream.agent_name || null,
    business_config_id: dbResult.business_config_id || null,
    pricing_version_id: dbResult.pricing_version_id || null,
    prices_created: dbResult.prices_created || 0,
    channel_insert_query: channelInsertQuery
  }
}];

const base = $("interpret_create_result").first().json;
const channelRow = $json || {};

return [{
  json: {
    ...base,
    channel_created: true,
    channel_id: channelRow.id || null
  }
}];

const base = $json || {};

return [{
  json: {
    ...base,
    channel_created: false,
    channel_id: null
  }
}];

const input = $json || {};

if (input.status === "forbidden") {
  return [{
    json: {
      ok: false,
      error: "forbidden",
      message: "El usuario no pertenece a esa organizacion.",
      agent_id: null
    }
  }];
}

if (input.status === "creation_failed") {
  return [{
    json: {
      ok: false,
      error: "creation_failed",
      message: "No se pudo crear el agente. Revisa el slug o intenta de nuevo.",
      agent_id: null
    }
  }];
}

return [{
  json: {
    ok: true,
    agent_id: input.agent_id,
    organization_id: input.organization_id,
    slug: input.slug,
    agent_name: input.agent_name,
    business_config_id: input.business_config_id,
    pricing_version_id: input.pricing_version_id,
    prices_created: input.prices_created,
    channel_created: input.channel_created || false,
    channel_id: input.channel_id || null
  }
}];

const input = $json || {};

return [{
  json: {
    ok: false,
    error: input.error || "invalid_request",
    agent_id: null
  }
}];
